package app.noir.mobile;
import org.json.*;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;
public final class BrowsingTest {
 @Test public void labelsMirrorDesktop(){long now=1792843200000L,day=86400000L;assertEquals("New season",StatusLabels.label(Arrays.asList(new StatusLabels.Episode(2,1,now-day),new StatusLabels.Episode(2,2,now+day)),now,0,false,false));assertEquals("New episode",StatusLabels.label(Arrays.asList(new StatusLabels.Episode(1,1,now-40*day),new StatusLabels.Episode(1,2,now-day),new StatusLabels.Episode(1,3,now+day)),now,0,false,false));assertEquals("Finale",StatusLabels.label(Arrays.asList(new StatusLabels.Episode(1,1,now-40*day),new StatusLabels.Episode(1,2,now-14*day)),now,0,false,false));assertEquals("",StatusLabels.label(Arrays.asList(new StatusLabels.Episode(0,1,now-day),new StatusLabels.Episode(1,1,now+day)),now,0,false,false));assertEquals("#7 this week",StatusLabels.label(Collections.emptyList(),now,7,false,false));assertEquals("",StatusLabels.label(Collections.emptyList(),now,0,true,false));assertEquals("Still planned",StatusLabels.label(Collections.emptyList(),now,0,true,true));}
 @Test public void layoutPersistsAndIgnoresUnknownRows()throws Exception{JSONArray json=new JSONArray("[{\"id\":\"services\"},{\"id\":\"continue\",\"visible\":false},{\"id\":\"list\",\"visible\":false},{\"id\":\"genre:Drama\",\"pinned\":true},{\"id\":\"removed\"},{\"id\":\"services\"}]");List<HomeLayout.Row> rows=HomeLayout.resolve(json,Arrays.asList("genre:Drama","collection:Weekend"));assertEquals("continue",rows.get(0).id);assertTrue(rows.get(0).visible);assertEquals("services",rows.get(1).id);assertFalse(rows.stream().anyMatch(r->r.id.equals("removed")));assertEquals(1,rows.stream().filter(r->r.id.equals("services")).count());assertFalse(rows.stream().filter(r->r.id.equals("list")).findFirst().get().visible);assertTrue(rows.stream().filter(r->r.id.equals("genre:Drama")).findFirst().get().pinned);assertFalse(rows.stream().filter(r->r.id.equals("collection:Weekend")).findFirst().get().visible);List<HomeLayout.Row> roundtrip=HomeLayout.resolve(new JSONArray(HomeLayout.encode(rows).toString()),Arrays.asList("genre:Drama","collection:Weekend"));assertEquals(rows.size(),roundtrip.size());assertEquals("continue",roundtrip.get(0).id);assertTrue(roundtrip.get(0).visible);}
}
